local({
  size <- coalesce(haven::zap_labels(DHucmm002), haven::zap_labels(EHucmm002))
  size <- case_when(survey_year == 2018 & size == 2 ~ 3, survey_year == 2018 & size == 3 ~ 2, .default = size)
  coalesce(recode_values(size, 1 ~ "Urban", 3 ~ "Suburban", 2 ~ "Rural"), "Unknown")
})

local({
  mo <- haven::zap_labels(DMtdmg029)
  fa <- haven::zap_labels(DFtdmg029)
  case_when(
    mo == 1 & fa == 1 ~ "Two biological/adoptive parents",
    (mo == 1 & fa %in% c(2, 9)) | (fa == 1 & mo %in% c(2, 9)) ~ "Single parent",
    mo %in% c(2, 9) & fa %in% c(2, 9) ~ "Other",
    .default = "Unknown"
  )
})

local({
  a <- carry_within(
    na_if(na_if(as.numeric(haven::zap_labels(DChmid006)), 99999999), 88888888) + 0.5,
    N_ID,
    order = wave
  )
  if_else(a > as.numeric(haven::zap_labels(DChdmg006)) / 12, NA_real_, a)
})

