local({
  rel <- coalesce(haven::zap_labels(DHuint005), haven::zap_labels(DChint005))
  who <- case_when(
    survey_year <= 2013 ~ "Unknown",
    rel %in% 1 ~ "Mother",
    rel %in% 2 ~ "Father",
    .default = NA_character_
  )
  m <- sapply(list(EMtcrs018, EMtcrs019, EMtcrs020, EMtcrs021, EMtcrs022, EMtcrs023), function(v) {
    as.numeric(haven::zap_labels(v))
  })
  f <- sapply(
    list(FFtcrs018, FFtcrs019, FFtcrs020, FFtcrs021, FFtcrs022, FFtcrs023, FFtcrs024, FFtcrs025),
    function(v) as.numeric(haven::zap_labels(v))
  )
  m[!m %in% 1:5] <- NA
  f[!f %in% 1:5] <- NA
  case_when(
    survey_year == 2011 ~ rowMeans(f),
    who %in% c("Mother", "Unknown") ~ rowMeans(m),
    who == "Father" ~ rowMeans(f[, 1:6]),
    .default = NA_real_
  )
})

local({
  m <- sapply(list(DMtcrs052, DMtcrs053, DMtcrs054, DMtcrs055), function(v) as.numeric(haven::zap_labels(v)))
  top <- if_else(survey_year == 2023, 4, 5)
  m[m < 1 | m > top] <- NA
  rowMeans(m)
})

