local({
  rel <- coalesce(haven::zap_labels(DHuint005), haven::zap_labels(DChint005))
  nocapi <- haven::zap_labels(DHuint001) %in% 0
  mo <- rel %in% 1 | (nocapi & haven::zap_labels(EMtint005) %in% 1)
  fa <- !mo & (rel %in% 2 | (nocapi & haven::zap_labels(FFtint005) %in% 1))
  m <- sapply(
    list(EMtfcs001, EMtfcs002, EMtfcs003, EMtfcs004, EMtfcs005, EMtfcs006, EMtfcs007, EMtfcs008, EMtfcs009, EMtfcs010),
    function(v) as.numeric(haven::zap_labels(v))
  )
  f <- sapply(
    list(FFtfcs001, FFtfcs002, FFtfcs003, FFtfcs004, FFtfcs005, FFtfcs006, FFtfcs007, FFtfcs008, FFtfcs009, FFtfcs010),
    function(v) as.numeric(haven::zap_labels(v))
  )
  m[!m %in% 1:5] <- NA
  f[!f %in% 1:5] <- NA
  case_when(mo ~ rowMeans(m), fa ~ rowMeans(f), .default = NA_real_)
})

local({
