local({
  wd <- coalesce(
    na_if(na_if(as.numeric(haven::zap_labels(DChdsc005a)), 99999999), 88888888),
    na_if(na_if(as.numeric(haven::zap_labels(JChdsc005a)), 99999999), 88888888)
  )
  we <- coalesce(
    na_if(na_if(as.numeric(haven::zap_labels(DChdsc005b)), 99999999), 88888888),
    na_if(na_if(as.numeric(haven::zap_labels(JChdsc005b)), 99999999), 88888888)
  )
  (5 * wd + 2 * we) / 7
})

