local({
  a <- sapply(list(IChcbc005, IChcbc006, IChcbc056, IChcbc059, IChcbc095), function(v) as.numeric(haven::zap_labels(v)))
  a[!a %in% 0:2] <- NA
  b <- sapply(
    list(IChcbl001, IChcbl004, IChcbl008, IChcbl010, IChcbl013, IChcbl017, IChcbl041, IChcbl061, IChcbl078, IChcbl080),
    function(v) as.numeric(haven::zap_labels(v))
  )
  b[!b %in% 0:2] <- NA
  coalesce(
    if_else(rowSums(!is.na(a)) >= 0.8 * ncol(a), rowMeans(a, na.rm = TRUE), NA_real_),
    if_else(rowSums(!is.na(b)) >= 0.8 * ncol(b), rowMeans(b, na.rm = TRUE), NA_real_)
  )
})

