local({
  kg <- coalesce(
    na_if(na_if(as.numeric(haven::zap_labels(EChhlt012)), 99999999), 88888888),
    na_if(na_if(as.numeric(haven::zap_labels(DChhlt012)), 99999999), 88888888),
    na_if(na_if(as.numeric(haven::zap_labels(JChhlt012)), 99999999), 88888888)
  )
  cm <- coalesce(
    na_if(na_if(as.numeric(haven::zap_labels(EChhlt013)), 99999999), 88888888),
    na_if(na_if(as.numeric(haven::zap_labels(DChhlt013)), 99999999), 88888888),
    na_if(na_if(as.numeric(haven::zap_labels(JChhlt013)), 99999999), 88888888)
  )
  kg / (cm / 100)^2
})

